# First, find all 9s with 8-dir neighbors
def has_8_dir_pattern_neighbor(r, c, grid, pattern):
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] == pattern:
                    return True
    return False

def has_4_dir_pattern_neighbor(r, c, grid, pattern):
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
